  'Cette carte est en ligne — un message vous proposera d’ouvrir une nouvelle carte…': ['This card is live — a message will offer to open a new card…', 'Esta tarjeta ya está en línea: un mensaje le propondrá abrir una tarjeta nueva…', 'Diese Karte ist online – eine Nachricht bietet an, eine neue Karte zu öffnen …', '此卡片已上线——发送消息时会询问是否开启新卡片…'],
  'Cette carte est déjà en ligne : votre message ouvrira une nouvelle carte, qui suivra tout le parcours.': ['This card is already live: your message will open a new card, which will follow the whole course.', 'Esta tarjeta ya está en línea: su mensaje abrirá una tarjeta nueva, que seguirá todo el recorrido.', 'Diese Karte ist bereits online: Ihre Nachricht öffnet eine neue Karte, die den ganzen Ablauf durchläuft.', '此卡片已上线：您的消息将开启一张新卡片，并走完整个流程。'],
