  'Nouvelle carte créée : votre demande y suit son parcours.': ['New card created: your request follows its course there.', 'Tarjeta nueva creada: su solicitud sigue allí su recorrido.', 'Neue Karte erstellt: Ihre Anfrage durchläuft dort ihren Ablauf.', '已创建新卡片：您的请求将在其中按流程推进。'],
