  'Répondez d’abord aux questions que l’agent a laissées sur la carte.': ['Answer the questions the agent left on the card first.', 'Responda primero a las preguntas que el agente dejó en la tarjeta.', 'Beantworten Sie zuerst die Fragen, die der Agent auf der Karte hinterlassen hat.', '请先回答智能体留在卡片上的问题。'],
