  'Une décision attend votre réponse : tranchez-la d’abord.': ['A decision is waiting for you: settle it first.', 'Una decisión espera su respuesta: resuélvala primero.', 'Eine Entscheidung wartet auf Sie: treffen Sie sie zuerst.', '有一个决定等待您的回复：请先做出决定。'],
  'Le lancement attend une vraie demande de travail, pas seulement une question.': ['Starting needs a real work request, not just a question.', 'El lanzamiento necesita una verdadera petición de trabajo, no solo una pregunta.', 'Der Start braucht einen echten Arbeitsauftrag, nicht nur eine Frage.', '启动需要一个真正的工作请求，而不只是一个问题。'],
  'Le plan est en cours de génération.': ['The plan is being generated.', 'El plan se está generando.', 'Der Plan wird erzeugt.', '方案正在生成中。'],
  'Ne pas attendre, lancer maintenant': ['Don’t wait, start now', 'No esperar, lanzar ahora', 'Nicht warten, jetzt starten', '不用等待，立即启动'],
