  'Rien ne tourne : il n’y a rien à suspendre.': ['Nothing is running: there is nothing to pause.', 'Nada está en marcha: no hay nada que pausar.', 'Nichts läuft: es gibt nichts zu pausieren.', '没有任何任务在运行：无需暂停。'],
