  'Étude': ['Study', 'Estudio', 'Untersuchung', '研究'],
  'Processus établi': ['Process set up', 'Proceso establecido', 'Prozess festgelegt', '流程已建立'],
  'Prêt à partir': ['Ready to run', 'Listo para salir', 'Startbereit', '可以开始'],
  'Essai réussi': ['Trial succeeded', 'Prueba superada', 'Probelauf erfolgreich', '试运行成功'],
  'À revérifier': ['To recheck', 'A revisar', 'Erneut prüfen', '需重新核对'],
  'L’agent attend votre réponse pour continuer son étude.': ['The agent is waiting for your answer to continue its study.', 'El agente espera su respuesta para continuar su estudio.', 'Der Agent wartet auf Ihre Antwort, um seine Untersuchung fortzusetzen.', '智能体正在等待您的回复，以便继续研究。'],
  'Étude en cours : l’agent étudie le projet et prépare le processus.': ['Study in progress: the agent is studying the project and preparing the process.', 'Estudio en curso: el agente estudia el proyecto y prepara el proceso.', 'Untersuchung läuft: Der Agent untersucht das Projekt und bereitet den Prozess vor.', '研究进行中：智能体正在研究项目并准备流程。'],
  'À configurer : l’agent doit d’abord étudier le projet, puis établir son processus.': ['To set up: the agent must first study the project, then set up its process.', 'Por configurar: el agente debe primero estudiar el proyecto y luego establecer su proceso.', 'Einzurichten: Der Agent muss zuerst das Projekt untersuchen und dann dessen Prozess festlegen.', '待配置：智能体需先研究项目，再建立其流程。'],
  'Prêt : le déroulé commun s’applique à chaque déploiement.': ['Ready: the common sequence applies to every deployment.', 'Listo: el desarrollo común se aplica en cada despliegue.', 'Bereit: Der gemeinsame Ablauf gilt für jede Bereitstellung.', '就绪：每次部署都使用通用流程。'],
  'Prêt : le processus est établi, et son dernier essai a réussi.': ['Ready: the process is set up, and its last trial succeeded.', 'Listo: el proceso está establecido y su última prueba salió bien.', 'Bereit: Der Prozess ist festgelegt, und sein letzter Probelauf war erfolgreich.', '就绪：流程已建立，且最近一次试运行成功。'],
  'Prêt : le processus est établi, il sera suivi au prochain clic.': ['Ready: the process is set up; it will be followed at the next click.', 'Listo: el proceso está establecido y se seguirá en el próximo clic.', 'Bereit: Der Prozess ist festgelegt und wird beim nächsten Klick befolgt.', '就绪：流程已建立，下次点击时将按其执行。'],
