  'Dossier': ['Folder', 'Carpeta', 'Ordner', '文件夹'],
  'Site extérieur': ['External site', 'Sitio externo', 'Externe Website', '外部站点'],
  'Le site à sauvegarder': ['The site to back up', 'El sitio a respaldar', 'Die zu sichernde Website', '要备份的站点'],
  'Un projet de ce serveur ?': [
    'A project on this server?',
    '¿Un proyecto de este servidor?',
    'Ein Projekt dieses Servers?',
    '本服务器的项目？',
  ],
  'Configurer': ['Configure', 'Configurar', 'Einrichten', '配置'],
  'Démarrage…': ['Starting…', 'Iniciando…', 'Wird gestartet…', '正在启动…'],
  'Décrivez le site en une phrase. L’agent d’analyse lit le site, écrit sa recette de backup (code, fichiers, bases), l’essaie pour de vrai, vous pose les questions qui restent, puis l’enregistre.':
    [
      'Describe the site in one sentence. The analysis agent reads the site, writes its backup recipe (code, files, databases), tests it for real, asks you the remaining questions, then saves it.',
      'Describa el sitio en una frase. El agente de análisis lee el sitio, escribe su receta de copia (código, archivos, bases), la prueba de verdad, le hace las preguntas pendientes y la guarda.',
      'Beschreiben Sie die Website in einem Satz. Der Analyse-Agent liest die Website, schreibt ihr Sicherungsrezept (Code, Dateien, Datenbanken), testet es wirklich, stellt Ihnen die offenen Fragen und speichert es.',
      '用一句话描述站点。分析代理会读取站点，编写其备份配方（代码、文件、数据库），实际测试，向您询问剩余问题，然后保存。',
    ],
  'Ex. : la boutique du client, un WordPress dans /var/www/boutique, à garder un mois': [
    'E.g. the client’s shop, a WordPress in /var/www/shop, kept for one month',
    'Ej.: la tienda del cliente, un WordPress en /var/www/tienda, conservado un mes',
    'Z. B. der Shop des Kunden, ein WordPress in /var/www/shop, einen Monat aufbewahrt',
    '例如：客户的商店，位于 /var/www/boutique 的 WordPress，保留一个月',
  ],
  'L’assistant configure ce site. Ses questions vous attendent dans la conversation.': [
    'The assistant is configuring this site. Its questions are waiting for you in the conversation.',
    'El asistente está configurando este sitio. Sus preguntas le esperan en la conversación.',
    'Der Assistent richtet diese Website ein. Seine Fragen warten im Gespräch auf Sie.',
    '助手正在配置该站点。它的问题在对话中等着您。',
  ],
  'L’assistant n’a pas pu démarrer': [
    'The assistant could not start',
    'El asistente no pudo iniciarse',
    'Der Assistent konnte nicht starten',
    '助手无法启动',
  ],
  'Dites au moins de quel site il s’agit : son nom, son adresse, ou son dossier sur le serveur.': [
    'At least say which site this is: its name, its address, or its folder on the server.',
    'Diga al menos de qué sitio se trata: su nombre, su dirección o su carpeta en el servidor.',
    'Sagen Sie zumindest, um welche Website es geht: Name, Adresse oder Ordner auf dem Server.',
    '至少说明是哪个站点：名称、地址，或它在服务器上的目录。',
  ],
  'Les identifiants trouvés ou donnés restent sur ce serveur : ils servent à relire la base et les fichiers du site, chaque nuit.':
    [
      'The credentials found or given stay on this server: they are used to read the site’s database and files, every night.',
      'Las credenciales encontradas o facilitadas permanecen en este servidor: sirven para releer la base y los archivos del sitio, cada noche.',
      'Die gefundenen oder angegebenen Zugangsdaten bleiben auf diesem Server: Sie dienen dazu, Datenbank und Dateien der Website jede Nacht zu lesen.',
      '找到或提供的凭据保存在本服务器：它们每晚用于读取该站点的数据库和文件。',
    ],
  'Disque de stockage : {dossier}': ['Storage disk: {dossier}', 'Disco de almacenamiento: {dossier}', 'Speicherlaufwerk: {dossier}', '存储磁盘：{dossier}'],
  'Tout sauvegarder': ['Back up everything', 'Copiar todo', 'Alles sichern', '全部备份'],
