  'Analyser': ['Analyze', 'Analizar', 'Analysieren', '分析'],
  'Faire écrire la recette de ce site par l’agent d’analyse': ['Have the analysis agent write this site’s recipe', 'Pedir al agente de análisis que escriba la receta de este sitio', 'Das Rezept dieser Website vom Analyse-Agenten schreiben lassen', '让分析代理为此站点编写配方'],
