  'Le point de montage du disque, chemin absolu. Vide, aucun backup ne part.': ['The disk mount point, an absolute path. Empty, no backup runs.', 'El punto de montaje del disco, ruta absoluta. Vacío, no se ejecuta ninguna copia.', 'Der Einhängepunkt des Laufwerks, absoluter Pfad. Leer, läuft kein Backup.', '磁盘挂载点，绝对路径。留空则不执行备份。'],
