  'Leçons et problèmes': ['Lessons and issues', 'Lecciones y problemas', 'Lektionen und Probleme', '经验与问题'],
  'La base de connaissances : les unités du Global et de chaque projet, leurs versions, les propositions refusées, le changelog de chaque projet et les rapports de génération, avec un rendu lisible par portée.': ['The knowledge base: the units of Global and of each project, their versions, refused proposals, each project’s changelog and generation reports, with a readable rendering per scope.', 'La base de conocimientos: las unidades del Global y de cada proyecto, sus versiones, las propuestas rechazadas, el registro de cambios de cada proyecto y los informes de generación, con una versión legible por ámbito.', 'Die Wissensbasis: die Einheiten von Global und jedem Projekt, ihre Versionen, abgelehnte Vorschläge, das Änderungsprotokoll jedes Projekts und die Erzeugungsberichte, dazu eine lesbare Fassung je Bereich.', '知识库：全局与每个项目的单元及其版本、被拒绝的提议、每个项目的更新日志和生成报告，并附每个范围的可读版本。'],
