  'Arrêter les {v0} agents de ce projet ?': ['Stop this project’s {v0} agents?', '¿Detener los {v0} agentes de este proyecto?', 'Die {v0} Agenten dieses Projekts stoppen?', '停止该项目的 {v0} 个智能体？'],
  'Arrêter les {v0} agents en cours sur tous les projets ?': ['Stop the {v0} running agents across all projects?', '¿Detener los {v0} agentes en curso en todos los proyectos?', 'Die {v0} laufenden Agenten in allen Projekten stoppen?', '停止所有项目中正在运行的 {v0} 个智能体？'],
  'Arrêter les agents du projet (': ['Stop the project’s agents (', 'Detener los agentes del proyecto (', 'Agenten des Projekts stoppen (', '停止该项目的智能体（'],
  'Arrêter tous les agents': ['Stop all agents', 'Detener todos los agentes', 'Alle Agenten stoppen', '停止所有智能体'],
  'Redémarrer le serveur ?': ['Restart the server?', '¿Reiniciar el servidor?', 'Server neu starten?', '重启服务器？'],
  'Redémarrer dès que possible': ['Restart as soon as possible', 'Reiniciar en cuanto sea posible', 'Neu starten, sobald möglich', '尽快重启'],
  'Forcer le redémarrage': ['Force the restart', 'Forzar el reinicio', 'Neustart erzwingen', '强制重启'],
  'Le redémarrage sera retenu et partira tout seul dès la fin du travail en cours.': [
    'The restart is held and will run on its own as soon as the current work finishes.',
    'El reinicio queda en espera y se ejecutará solo en cuanto termine el trabajo en curso.',
    'Der Neustart wird zurückgehalten und läuft von selbst, sobald die laufende Arbeit fertig ist.',
    '重启请求会被保留，当前工作结束后自动执行。',
  ],
  "Beluga Build ne peut pas s'éteindre depuis sa propre interface": [
    'Beluga Build cannot shut itself down from its own interface',
    'Beluga Build no puede apagarse desde su propia interfaz',
    'Beluga Build kann sich nicht über die eigene Oberfläche beenden',
    'Beluga Build 无法从自身界面关闭',
  ],
  'Le travail en cours sera perdu. Les agents des autres projets continuent.': [
    'Work in progress will be lost. Agents on other projects keep going.',
    'El trabajo en curso se perderá. Los agentes de otros proyectos continúan.',
    'Laufende Arbeit geht verloren. Agenten anderer Projekte laufen weiter.',
    '进行中的工作将丢失。其他项目的智能体继续运行。',
  ],
  'Chaque moteur est coupé sur-le-champ, sur tous les projets. Le travail déjà écrit reste sur la branche de sa carte ; c’est la réflexion en cours qui s’arrête.': [
    'Every engine is cut off at once, across all projects. Work already written stays on its card’s branch; it is the reasoning in progress that stops.',
    'Cada motor se corta de inmediato, en todos los proyectos. El trabajo ya escrito permanece en la rama de su tarjeta; lo que se detiene es el razonamiento en curso.',
    'Jede Engine wird sofort abgeschaltet, in allen Projekten. Bereits geschriebene Arbeit bleibt im Branch ihrer Karte; nur das laufende Nachdenken hört auf.',
    '所有项目的引擎立即中断。已写入的工作保留在卡片分支上，停止的只是进行中的推理。',
  ],
  'Le service redémarre avec sa commande habituelle.': ['The service restarts with its usual command.', 'El servicio se reinicia con su comando habitual.', 'Der Dienst startet mit seinem üblichen Befehl neu.', '服务以其常用命令重启。'],
  'Le service s’arrête tout de suite. Ce qu’il servait devient injoignable jusqu’au redémarrage.': [
    'The service stops immediately. What it served becomes unreachable until the restart.',
    'El servicio se detiene enseguida. Lo que servía queda inaccesible hasta el reinicio.',
    'Der Dienst hält sofort an. Was er auslieferte, ist bis zum Neustart nicht erreichbar.',
    '服务立即停止。它所提供的内容在重启前无法访问。',
  ],
