  '2. La page finit sur une erreur « localhost » : c’est normal. Copiez son adresse complète, puis collez-la ici.': ['2. The page ends on a “localhost” error: that is expected. Copy its full address, then paste it here.', '2. La página termina en un error «localhost»: es normal. Copie su dirección completa y péguela aquí.', '2. Die Seite endet mit einem „localhost“-Fehler: Das ist normal. Kopieren Sie die vollständige Adresse und fügen Sie sie hier ein.', '2. 页面最后会显示“localhost”错误：这是正常的。复制完整地址，然后粘贴到这里。'],
