  'Mise en production terminée': ['Go-live complete', 'Puesta en producción terminada', 'Produktivsetzung abgeschlossen', '上线已完成'],
  'Mise en production impossible': ['Go-live impossible', 'Puesta en producción imposible', 'Produktivsetzung nicht möglich', '无法上线'],
  'Mise en production en cours': ['Go-live in progress', 'Puesta en producción en curso', 'Produktivsetzung läuft', '正在上线'],
  'Mise en production en échec': ['Go-live failed', 'Puesta en producción fallida', 'Produktivsetzung fehlgeschlagen', '上线失败'],
  'Mise en production arrêtée': ['Go-live stopped', 'Puesta en producción detenida', 'Produktivsetzung angehalten', '上线已停止'],
