  'Démarrer par un cahier des charges': ['Start with a specification', 'Empezar con un pliego de condiciones', 'Mit einem Lastenheft beginnen', '从需求规格书开始'],
  'Une carte « Cahier des charges » apparaît dans le projet : son agent vous pose les questions une à une, rédige le cahier des charges sous vos yeux, puis le plan de construction. On peut le mettre en pause et le reprendre plus tard.': [
    'A “Specification” card appears in the project: its agent asks you the questions one by one, writes the specification as you watch, then the build plan. You can pause it and resume later.',
    'Aparece una tarjeta «Pliego de condiciones» en el proyecto: su agente le hace las preguntas una a una, redacta el pliego ante sus ojos y luego el plan de construcción. Se puede pausar y retomar más tarde.',
    'Im Projekt erscheint eine Karte „Lastenheft“: Ihr Agent stellt Ihnen die Fragen nacheinander, schreibt das Lastenheft vor Ihren Augen und danach den Bauplan. Man kann es pausieren und später fortsetzen.',
    '项目中会出现一张“需求规格书”卡片：它的智能体逐一向您提问，当着您的面撰写规格书，然后撰写构建计划。可以暂停，稍后继续。',
  ],
