    'Xiaomi veröffentlicht das Abo-Guthaben nicht: Der Monatsbalken beginnt bei dem unter Einstellungen › Konten eingetragenen Wert und addiert, was Beluga sendet. Er ist geschätzt: Die Nutzung desselben Schlüssels außerhalb von Beluga wird nicht gezählt.',
