  /* ---- Export et import intégral des données ---------------------- */
  'Export et import des données': ['Data export and import', 'Exportación e importación de datos', 'Datenexport und -import', '数据导出与导入'],
  'Emporter le coffre-fort, les backups, les projets, les cartes, les conversations et les branches dans une seule archive — puis les remonter sur une autre installation.': ['Take the vault, the backups, the projects, the cards, the conversations and the branches away in a single archive — then restore them on another installation.', 'Llévese la caja fuerte, las copias de seguridad, los proyectos, las tarjetas, las conversaciones y las ramas en un único archivo, y restáurelos en otra instalación.', 'Tresor, Backups, Projekte, Karten, Gespräche und Branches in einem einzigen Archiv mitnehmen — und auf einer anderen Installation wiederherstellen.', '把保险库、备份、项目、卡片、对话和分支装进一个压缩包带走，再在另一套安装中还原。'],
  'Ouvrir': ['Open', 'Abrir', 'Öffnen', '打开'],
  'Exporter': ['Export', 'Exportar', 'Exportieren', '导出'],
  'Importer': ['Import', 'Importar', 'Importieren', '导入'],
  'Une archive ZIP de tout ce que cette installation garde, lisible telle quelle et remontable sur un autre serveur. Les valeurs sensibles y sont en clair : c’est ce qui permet de retrouver ses accès en face.': ['A ZIP archive of everything this installation holds, readable as is and restorable on another server. Sensitive values are in clear text: that is what lets you find your credentials again on the other side.', 'Un archivo ZIP con todo lo que guarda esta instalación, legible tal cual y restaurable en otro servidor. Los valores sensibles están en claro: es lo que permite recuperar los accesos al otro lado.', 'Ein ZIP-Archiv mit allem, was diese Installation verwahrt, so lesbar wie es ist und auf einem anderen Server wiederherstellbar. Sensible Werte stehen im Klartext: nur so findet man seine Zugänge drüben wieder.', '本安装所保存内容的 ZIP 压缩包，可直接阅读，也可在另一台服务器上还原。敏感值以明文保存：正是它让您在对面重新找回访问凭据。'],
  'Machine d’origine : {v0}': ['Source machine: {v0}', 'Máquina de origen: {v0}', 'Ursprungsrechner: {v0}', '来源机器：{v0}'],
  'Tout cocher': ['Check all', 'Marcar todo', 'Alle auswählen', '全选'],
  'Tout décocher': ['Uncheck all', 'Desmarcar todo', 'Alle abwählen', '全部取消'],
  'Lecture des données…': ['Reading the data…', 'Leyendo los datos…', 'Daten werden gelesen…', '正在读取数据…'],
