  '{n} dépôt(s) git': ['{n} git repo(s)', '{n} repositorio(s) git', '{n} Git-Repository(s)', '{n} 个 Git 仓库'],
  'Créer et télécharger l’archive': ['Create and download the archive', 'Crear y descargar el archivo', 'Archiv erstellen und herunterladen', '创建并下载压缩包'],
  'Fabrication de l’archive…': ['Building the archive…', 'Creando el archivo…', 'Archiv wird erstellt…', '正在生成压缩包…'],
  'Archive prête : {v0}': ['Archive ready: {v0}', 'Archivo listo: {v0}', 'Archiv fertig: {v0}', '压缩包已就绪：{v0}'],
  'Export impossible': ['Export failed', 'Exportación imposible', 'Export nicht möglich', '导出失败'],
  'Sans « {v0} », ce qui s’y accroche arrivera sans son rattachement.': ['Without “{v0}”, whatever hangs off it will arrive with nothing to attach to.', 'Sin «{v0}», lo que depende de ello llegará sin su vínculo.', 'Ohne „{v0}“ kommt alles, was daran hängt, ohne seine Zuordnung an.', '缺少「{v0}」时，依附于它的内容将失去归属。'],
  'Déposez une archive écrite par un autre Beluga Build. Elle est vérifiée avant toute écriture : version, contenu et empreinte de chaque fichier.': ['Drop an archive written by another Beluga Build. It is checked before anything is written: version, contents and fingerprint of every file.', 'Suelte un archivo escrito por otro Beluga Build. Se comprueba antes de escribir nada: versión, contenido y huella de cada fichero.', 'Legen Sie ein von einem anderen Beluga Build geschriebenes Archiv ab. Es wird vor jedem Schreibvorgang geprüft: Version, Inhalt und Prüfsumme jeder Datei.', '请上传由另一套 Beluga Build 生成的压缩包。写入前会先校验：版本、内容以及每个文件的指纹。'],
  'Choisir une archive': ['Choose an archive', 'Elegir un archivo', 'Archiv auswählen', '选择压缩包'],
  'Lecture de l’archive…': ['Reading the archive…', 'Leyendo el archivo…', 'Archiv wird gelesen…', '正在读取压缩包…'],
  'Archive refusée.': ['Archive refused.', 'Archivo rechazado.', 'Archiv abgelehnt.', '压缩包已被拒绝。'],
  'Archive de « {v0} », écrite le {v1} par la version {v2}.': ['Archive from “{v0}”, written on {v1} by version {v2}.', 'Archivo de «{v0}», escrito el {v1} por la versión {v2}.', 'Archiv von „{v0}“, geschrieben am {v1} von Version {v2}.', '来自「{v0}」的压缩包，由版本 {v2} 于 {v1} 生成。'],
  'Fiches déjà présentes ici': ['Records already here', 'Fichas ya presentes aquí', 'Bereits vorhandene Einträge', '此处已存在的条目'],
  'Importer maintenant': ['Import now', 'Importar ahora', 'Jetzt importieren', '立即导入'],
  'Remontée en cours…': ['Restoring…', 'Restaurando…', 'Wird wiederhergestellt…', '正在还原…'],
  'Import impossible': ['Import failed', 'Importación imposible', 'Import nicht möglich', '导入失败'],
  'Import terminé : {n} table(s) remontée(s).': ['Import finished: {n} table(s) restored.', 'Importación terminada: {n} tabla(s) restaurada(s).', 'Import abgeschlossen: {n} Tabelle(n) wiederhergestellt.', '导入完成：已还原 {n} 张表。'],
  '{v0} ajoutée(s), {v1} remplacée(s), {v2} laissée(s), {v3} refusée(s).': ['{v0} added, {v1} replaced, {v2} kept, {v3} refused.', '{v0} añadidas, {v1} reemplazadas, {v2} conservadas, {v3} rechazadas.', '{v0} hinzugefügt, {v1} ersetzt, {v2} behalten, {v3} abgelehnt.', '新增 {v0}，替换 {v1}，保留 {v2}，拒绝 {v3}。'],
  '{v0} / {v1}': ['{v0} / {v1}', '{v0} / {v1}', '{v0} / {v1}', '{v0} / {v1}'],
  'Les dépôts git ne sont pas reclonés tout seuls : leur état et un script de reprise sont déposés dans les données du serveur.': ['Git repositories are not re-cloned on their own: their state and a resume script are dropped into the server data.', 'Los repositorios git no se vuelven a clonar solos: su estado y un script de reanudación quedan en los datos del servidor.', 'Git-Repositories werden nicht von selbst neu geklont: Ihr Zustand und ein Wiederaufnahme-Skript werden in den Serverdaten abgelegt.', 'Git 仓库不会自动重新克隆：其状态和一份恢复脚本会存放在服务器数据中。'],

