  'Les réglages du système, les préférences d’affichage, les comptes moteur et les clés d’accès.': ['System settings, display preferences, engine accounts and access keys.', 'Los ajustes del sistema, las preferencias de visualización, las cuentas de motor y las claves de acceso.', 'Systemeinstellungen, Anzeigepräferenzen, Engine-Konten und Zugangsschlüssel.', '系统设置、显示偏好、引擎账户与访问密钥。'],
  'La liste des projets pilotés, leurs réglages propres et les groupes de la colonne de gauche.': ['The list of piloted projects, their own settings and the groups in the left-hand column.', 'La lista de proyectos gestionados, sus ajustes propios y los grupos de la columna izquierda.', 'Die Liste der gesteuerten Projekte, ihre eigenen Einstellungen und die Gruppen der linken Spalte.', '受管项目列表、各自的设置以及左侧栏的分组。'],
  'Toutes les cartes de tous les tableaux, avec leurs étiquettes, leurs commentaires et les propositions en attente.': ['Every card of every board, with its labels, its comments and the pending proposals.', 'Todas las tarjetas de todos los tableros, con sus etiquetas, sus comentarios y las propuestas pendientes.', 'Alle Karten aller Boards, mit ihren Etiketten, ihren Kommentaren und den offenen Vorschlägen.', '所有看板的全部卡片，包含标签、评论以及待处理的提议。'],
  'Les fils de discussion avec les agents, leurs messages, leur file d’attente et les pièces jointes.': ['The threads with the agents, their messages, their queue and the attachments.', 'Los hilos con los agentes, sus mensajes, su cola de espera y los adjuntos.', 'Die Verläufe mit den Agenten, ihre Nachrichten, ihre Warteschlange und die Anhänge.', '与智能体的会话、消息、排队内容与附件。'],
  'Les mises en ligne passées, la consommation, les quotas mesurés et les journaux d’analyse.': ['Past deployments, consumption, measured quotas and the analysis logs.', 'Las publicaciones pasadas, el consumo, las cuotas medidas y los registros de análisis.', 'Vergangene Veröffentlichungen, Verbrauch, gemessene Kontingente und die Analyseprotokolle.', '过往上线记录、消耗量、已测额度与分析日志。'],
  'Tous les accès rangés dans le coffre-fort, valeurs comprises.': ['Every credential stored in the vault, values included.', 'Todos los accesos guardados en la caja fuerte, valores incluidos.', 'Alle im Tresor abgelegten Zugänge, samt Werten.', '保险库中保存的全部访问凭据，含其取值。'],
  'Les sites configurés pour être sauvegardés et la liste de leurs points de restauration.': ['The sites set up to be backed up and the list of their restore points.', 'Los sitios configurados para copia de seguridad y la lista de sus puntos de restauración.', 'Die zur Sicherung eingerichteten Websites und die Liste ihrer Wiederherstellungspunkte.', '已配置备份的站点及其还原点列表。'],
  'Les surveillances, leur recette de contrôle et l’historique de leurs passages des dernières 24 heures.': ['The monitors, their check recipe and the history of their checks over the last 24 hours.', 'Las supervisiones, su receta de control y el historial de sus pasadas de las últimas 24 horas.', 'Die Überwachungen, ihr Prüfrezept und der Verlauf ihrer Prüfungen der letzten 24 Stunden.', '监控项、其检查方案以及最近 24 小时的检查记录。'],
  'Pour chaque projet : son dépôt d’origine, sa branche courante et toutes ses branches avec leur dernier enregistrement.': ['For each project: its origin repository, its current branch and every branch with its latest commit.', 'Para cada proyecto: su repositorio de origen, su rama actual y todas sus ramas con su último registro.', 'Für jedes Projekt: sein Ursprungs-Repository, sein aktueller Branch und alle Branches mit ihrem letzten Commit.', '每个项目的来源仓库、当前分支，以及全部分支及其最新提交。'],
  'Garder ce qui est déjà ici': ['Keep what is already here', 'Conservar lo que ya está aquí', 'Behalten, was schon hier ist', '保留此处已有内容'],
  'Écraser avec l’archive': ['Overwrite with the archive', 'Sobrescribir con el archivo', 'Mit dem Archiv überschreiben', '用压缩包覆盖'],
  'Vider puis remplir avec l’archive': ['Empty, then fill from the archive', 'Vaciar y luego llenar con el archivo', 'Leeren und dann aus dem Archiv füllen', '先清空再用压缩包填充'],
  'Une fiche portant le même identifiant est laissée telle quelle. Rien ne peut être perdu.': ['A record with the same identifier is left untouched. Nothing can be lost.', 'Una ficha con el mismo identificador se deja tal cual. Nada puede perderse.', 'Ein Eintrag mit derselben Kennung bleibt unverändert. Nichts kann verloren gehen.', '同一标识的条目保持原样。不会丢失任何内容。'],
  'Une fiche portant le même identifiant est remplacée par celle de l’archive.': ['A record with the same identifier is replaced by the one from the archive.', 'Una ficha con el mismo identificador se sustituye por la del archivo.', 'Ein Eintrag mit derselben Kennung wird durch den aus dem Archiv ersetzt.', '同一标识的条目将被压缩包中的条目替换。'],
  'Chaque table emportée est vidée avant d’être remplie. À réserver à un serveur neuf.': ['Every table taken is emptied before being filled. For a brand-new server only.', 'Cada tabla incluida se vacía antes de llenarse. Resérvelo para un servidor nuevo.', 'Jede mitgenommene Tabelle wird vor dem Füllen geleert. Nur für einen neuen Server.', '所涉每张表在填充前都会被清空。仅适用于全新服务器。'],

