  'Ouvrez l’environnement de développement à une autre personne : vous choisissez, projet par projet et service par service, ce qu’elle peut voir et faire. Les comptes de vos clients se créent depuis la messagerie.': ['Open the development environment to another person: you choose, project by project and service by service, what they can see and do. Your clients’ accounts are created from the messaging.', 'Abra el entorno de desarrollo a otra persona: usted elige, proyecto por proyecto y servicio por servicio, lo que puede ver y hacer. Las cuentas de sus clientes se crean desde la mensajería.', 'Öffnen Sie die Entwicklungsumgebung für eine andere Person: Sie wählen Projekt für Projekt und Dienst für Dienst, was sie sehen und tun kann. Die Konten Ihrer Kunden werden über die Nachrichten erstellt.', '向他人开放开发环境：您可以逐个项目、逐个服务选择其可查看和操作的内容。客户账户在消息中创建。'],
