  'Client': ['Client', 'Cliente', 'Kunde', '客户'],
  'Travaille dans les projets cochés : cartes, conversations, agents. Ni mise en ligne, ni comptes, ni coffre-fort, ni réglages.': ['Works in the ticked projects: cards, conversations, agents. No publishing, no accounts, no vault, no settings.', 'Trabaja en los proyectos marcados: tarjetas, conversaciones, agentes. Sin publicación, sin cuentas, sin caja fuerte, sin ajustes.', 'Arbeitet in den angekreuzten Projekten: Karten, Unterhaltungen, Agenten. Keine Veröffentlichung, keine Konten, kein Tresor, keine Einstellungen.', '在勾选的项目中工作：卡片、对话、代理。不能发布，不能管理账户，不能使用保险库，不能更改设置。'],
  'Voit les projets cochés sans rien modifier.': ['Sees the ticked projects without changing anything.', 'Ve los proyectos marcados sin modificar nada.', 'Sieht die angekreuzten Projekte, ohne etwas zu ändern.', '可以查看勾选的项目，但不能修改任何内容。'],
  'N’a que l’espace client : ses demandes sur les projets cochés.': ['Only has the client area: their requests on the ticked projects.', 'Solo tiene el espacio cliente: sus solicitudes en los proyectos marcados.', 'Hat nur den Kundenbereich: seine Anfragen zu den angekreuzten Projekten.', '只能使用客户空间：查看勾选项目上自己的请求。'],
  'Un agent lit le journal des changements du dépôt public et met les nouveautés en place, dans une tâche que vous suivez dans le projet Beluga Build. Rien n’est mis en ligne sans vous.': ['An agent reads the public repository’s change log and puts the updates in place, in a task you follow in the Beluga Build project. Nothing goes live without you.', 'Un agente lee el registro de cambios del repositorio público y aplica las novedades, en una tarea que usted sigue en el proyecto Beluga Build. Nada se publica sin usted.', 'Ein Agent liest das Änderungsprotokoll des öffentlichen Repositorys und spielt die Neuerungen ein, in einer Aufgabe, die Sie im Projekt Beluga Build verfolgen. Ohne Sie geht nichts online.', '代理会阅读公共仓库的更新日志并落实更新，任务显示在 Beluga Build 项目中，由您跟进。未经您同意，不会上线任何内容。'],
  'La mise à jour est lancée : un agent lit le journal des changements et met les nouveautés en place. Suivez la tâche dans le projet Beluga Build.': ['The update has started: an agent reads the change log and puts the updates in place. Follow the task in the Beluga Build project.', 'La actualización ha empezado: un agente lee el registro de cambios y aplica las novedades. Siga la tarea en el proyecto Beluga Build.', 'Das Update läuft: Ein Agent liest das Änderungsprotokoll und spielt die Neuerungen ein. Verfolgen Sie die Aufgabe im Projekt Beluga Build.', '更新已开始：代理正在阅读更新日志并落实更新。请在 Beluga Build 项目中跟进该任务。'],
  'La tâche de mise à jour est prête dans le projet Beluga Build, mais elle n’a pas pu partir : {raison}': ['The update task is ready in the Beluga Build project, but it could not start: {raison}', 'La tarea de actualización está lista en el proyecto Beluga Build, pero no ha podido empezar: {raison}', 'Die Update-Aufgabe liegt im Projekt Beluga Build bereit, konnte aber nicht starten: {raison}', '更新任务已在 Beluga Build 项目中就绪，但未能启动：{raison}'],
  'Mises à jour': ['Updates', 'Actualizaciones', 'Updates', '更新'],
  'Mon compte': ['My account', 'Mi cuenta', 'Mein Konto', '我的账户'],
