  'En attente par projet': ['Waiting, by project', 'En espera por proyecto', 'Offen nach Projekt', '各项目的待办'],
  'Rien n’attend, dans aucun projet.': ['Nothing is waiting, in any project.', 'Nada está en espera, en ningún proyecto.', 'In keinem Projekt steht etwas aus.', '所有项目都没有待办事项。'],
  'Aucun travail en cours.': ['Nothing in progress.', 'Ningún trabajo en curso.', 'Nichts in Arbeit.', '暂无进行中的工作。'],
