  'Visites des 28 derniers jours comparées aux 28 jours d’avant': ['Visits over the last 28 days compared with the 28 days before', 'Visitas de los últimos 28 días comparadas con los 28 días anteriores', 'Besuche der letzten 28 Tage im Vergleich zu den 28 Tagen davor', '最近 28 天的访问量与前 28 天相比'],
