  'Audience': ['Audience', 'Audiencia', 'Reichweite', '受众'],
  'Parcours': ['Journeys', 'Recorridos', 'Besucherwege', '访问路径'],
  'Les chiffres arrivent dès que le code de suivi est posé sur le site.': ['Figures arrive as soon as the tracking code is on the site.', 'Las cifras llegan en cuanto el código de seguimiento está en el sitio.', 'Die Zahlen kommen, sobald der Tracking-Code auf der Website ist.', '统计代码放到网站上后，数据就会出现。'],
  'Clics par repère': ['Clicks per marker', 'Clics por marcador', 'Klicks pro Markierung', '各标记点击数'],
