  '(texte vide)': ['(empty text)', '(texto vacío)', '(leerer Text)', '（空文本）'],
  '{n} mots calés sur la voix.': ['{n} words timed to the voice.', '{n} palabras sincronizadas con la voz.', '{n} Wörter auf die Stimme abgestimmt.', '{n} 个词已与语音对齐。'],
  '{n} voix d’essai': ['{n} trial voice(s)', '{n} voz(ces) de prueba', '{n} Probestimme(n)', '{n} 个试听语音'],
  '{n} voix d’essai prête(s).': ['{n} trial voice(s) ready.', '{n} voz(ces) de prueba lista(s).', '{n} Probestimme(n) bereit.', '{n} 个试听语音已就绪。'],
  '{n} voix sont encore en voix d’essai : l’export les gardera telles quelles.': ['{n} voices are still trial voices: the export will keep them as they are.', '{n} voces siguen siendo de prueba: la exportación las mantendrá tal cual.', '{n} Stimmen sind noch Probestimmen: Der Export übernimmt sie unverändert.', '仍有 {n} 个语音为试听语音：导出时将保持原样。'],
  '{t} s / {d} s': ['{t} s / {d} s', '{t} s / {d} s', '{t} s / {d} s', '{t} 秒 / {d} 秒'],
  'À revalider': ['To revalidate', 'Por revalidar', 'Erneut bestätigen', '需重新确认'],
  'Annulé': ['Cancelled', 'Cancelado', 'Abgebrochen', '已取消'],
  'Annuler (Ctrl+Z)': ['Undo (Ctrl+Z)', 'Deshacer (Ctrl+Z)', 'Rückgängig (Strg+Z)', '撤销 (Ctrl+Z)'],
  'Annuaire exploré': ['Directory explored', 'Directorio explorado', 'Verzeichnis durchsucht', '目录已探索'],
  'Vérification à refaire': ['Check to redo', 'Verificación por repetir', 'Prüfung erneut nötig', '需重新验证'],
  'Passer la vérification': ['Pass the check', 'Pasar la verificación', 'Prüfung bestehen', '完成验证'],
  'Passer la vérification — {nom}': ['Pass the check — {nom}', 'Pasar la verificación — {nom}', 'Prüfung bestehen — {nom}', '完成验证 — {nom}'],
  'Ce navigateur tourne sur le serveur. Touchez l’image comme la page elle-même pour passer la vérification, puis appuyez sur « C’est fait » : la source sera lue par ce navigateur, et le restera chaque nuit.': ['This browser runs on the server. Tap the image as you would the page itself to pass the check, then press “Done”: the source will be read through this browser, every night from now on.', 'Este navegador funciona en el servidor. Toca la imagen como si fuera la propia página para pasar la verificación y pulsa «Hecho»: la fuente se leerá con este navegador, también cada noche.', 'Dieser Browser läuft auf dem Server. Tippen Sie auf das Bild wie auf die Seite selbst, um die Prüfung zu bestehen, und drücken Sie dann „Erledigt“: Die Quelle wird mit diesem Browser gelesen, auch jede Nacht.', '此浏览器运行在服务器上。像操作页面本身一样点击图像以完成验证，然后点“完成”：此来源将通过这个浏览器读取，之后每晚也是如此。'],
  'Page du navigateur': ['Browser page', 'Página del navegador', 'Browserseite', '浏览器页面'],
  'Le navigateur est fermé.': ['The browser is closed.', 'El navegador está cerrado.', 'Der Browser ist geschlossen.', '浏览器已关闭。'],
  'Ouverture du navigateur…': ['Opening the browser…', 'Abriendo el navegador…', 'Browser wird geöffnet…', '正在打开浏览器…'],
  'Lecture de la source par ce navigateur…': ['Reading the source through this browser…', 'Leyendo la fuente con este navegador…', 'Quelle wird mit diesem Browser gelesen…', '正在通过此浏览器读取来源…'],
  'Texte à taper dans la page': ['Text to type in the page', 'Texto para escribir en la página', 'Text, der in die Seite getippt wird', '要在页面中输入的文字'],
  'Taper': ['Type', 'Escribir', 'Tippen', '输入'],
  'Touche Entrée': ['Enter key', 'Tecla Intro', 'Eingabetaste', '回车键'],
  'Effacer un caractère': ['Delete a character', 'Borrar un carácter', 'Ein Zeichen löschen', '删除一个字符'],
