  'Style : kit de marque, médias et modèles du projet': ['Style: brand kit, media and templates of the project', 'Estilo: kit de marca, medios y plantillas del proyecto', 'Stil: Markenkit, Medien und Vorlagen des Projekts', '风格：项目的品牌套件、媒体和模板'],
