  'Aucune licence notée pour ce son : notez-la dans la bibliothèque avant de publier.': ['No licence noted for this sound: note it in the library before publishing.', 'No hay licencia anotada para este sonido: anótala en la biblioteca antes de publicar.', 'Für diesen Ton ist keine Lizenz notiert: Tragen Sie sie vor der Veröffentlichung in der Bibliothek ein.', '此音频未注明许可：发布前请在素材库中注明。'],
  'Aucune voix : ajoutez un segment « Voix » ou demandez-le à l’agent.': ['No voice: add a “Voice” segment or ask the agent.', 'Sin voz: añade un segmento «Voz» o pídeselo al agente.', 'Keine Stimme: Fügen Sie ein „Stimme“-Segment hinzu oder bitten Sie den Agenten darum.', '没有语音：添加一个「语音」片段，或让智能体来做。'],
