  'Ce dessin n’a déclaré aucun réglage : demandez-en à l’agent, ou déplacez ses pièces dans l’aperçu.': ['This drawing declares no settings: ask the agent for some, or move its pieces in the preview.', 'Este dibujo no declara ningún ajuste: pídeselos al agente o mueve sus piezas en la vista previa.', 'Diese Zeichnung hat keine Einstellungen: Bitten Sie den Agenten darum oder verschieben Sie ihre Teile in der Vorschau.', '此图形未声明任何设置：请让智能体添加，或在预览中移动其元素。'],
