  'L’agent du studio dessine vos visuels en code, pièce par pièce : vous gardez la main sur chaque texte, couleur et position. Il prépare aussi les voix d’essai et les sous-titres.': ['The studio agent draws your visuals in code, piece by piece: you keep control of every text, colour and position. It also prepares the trial voices and the subtitles.', 'El agente del estudio dibuja tus visuales en código, pieza a pieza: conservas el control de cada texto, color y posición. También prepara las voces de prueba y los subtítulos.', 'Der Studio-Agent zeichnet Ihre Visuals in Code, Teil für Teil: Sie behalten jeden Text, jede Farbe und Position in der Hand. Er bereitet auch die Probestimmen und die Untertitel vor.', '工作室智能体用代码逐个绘制你的视觉素材：每个文字、颜色和位置都由你掌控。它还会准备试听语音和字幕。'],
