  'Ses versions, ses voix et ses exports seront effacés. Les fichiers importés restent dans la bibliothèque du projet.': ['Its versions, voices and exports will be deleted. Imported files stay in the project library.', 'Se borrarán sus versiones, voces y exportaciones. Los archivos importados se quedan en la biblioteca del proyecto.', 'Ihre Versionen, Stimmen und Exporte werden gelöscht. Importierte Dateien bleiben in der Projektbibliothek.', '其版本、语音和导出将被删除。导入的文件会保留在项目素材库中。'],
