  'Un dessin a une erreur : {erreur}': ['A drawing has an error: {erreur}', 'Un dibujo tiene un error: {erreur}', 'Eine Zeichnung hat einen Fehler: {erreur}', '某个图形出错：{erreur}'],
  'Une création est un visuel ou une courte vidéo animée, faite de pièces séparées qu’on retouche à tout moment. L’agent du studio les dessine pour vous, puis vous l’exportez aux formats des réseaux.': ['A creation is a visual or a short animated video, made of separate pieces you can adjust at any time. The studio agent draws them for you, then you export it in the social network formats.', 'Una creación es un visual o un vídeo animado corto, hecho de piezas separadas que se retocan en cualquier momento. El agente del estudio las dibuja por ti y luego la exportas en los formatos de las redes.', 'Eine Kreation ist ein Visual oder ein kurzes animiertes Video aus einzelnen Teilen, die sich jederzeit anpassen lassen. Der Studio-Agent zeichnet sie für Sie, dann exportieren Sie sie in den Formaten der Netzwerke.', '作品是由可随时调整的独立元素组成的视觉素材或动画短视频。工作室智能体为你绘制，然后你可按各社交平台的格式导出。'],
  'Une vidéo de 15 secondes qui présente notre nouvelle offre, ton enjoué…': ['A 15-second video introducing our new offer, upbeat tone…', 'Un vídeo de 15 segundos que presente nuestra nueva oferta, tono alegre…', 'Ein 15-Sekunden-Video, das unser neues Angebot vorstellt, fröhlicher Ton…', '一段 15 秒的视频，介绍我们的新方案，语气轻快……'],
  'Une vidéo prend environ trois fois et demie sa durée à fabriquer, une à la fois sur le serveur.': ['A video takes about three and a half times its length to render, one at a time on the server.', 'Un vídeo tarda unas tres veces y media su duración en fabricarse, uno a la vez en el servidor.', 'Ein Video braucht etwa das Dreieinhalbfache seiner Länge zur Erstellung, eines nach dem anderen auf dem Server.', '生成一段视频大约需要其时长的三倍半，服务器一次只处理一个。'],
