  'Le marqueur bleu de la ligne de temps : la vidéo s’arrête là, à l’aperçu comme à l’export.': ['The blue marker on the timeline: the video stops there, in the preview as in the export.', 'El marcador azul de la línea de tiempo: el vídeo se detiene ahí, en la vista previa y en la exportación.', 'Die blaue Markierung der Zeitleiste: Das Video endet dort, in der Vorschau wie im Export.', '时间轴上的蓝色标记：视频在此结束，预览和导出都一样。'],
