  'Modèle copié, mais {n} fichier(s) introuvable(s) n’ont pas suivi.': ['Template copied, but {n} missing file(s) did not follow.', 'Plantilla copiada, pero {n} archivo(s) no encontrado(s) no se copiaron.', 'Vorlage kopiert, aber {n} fehlende Datei(en) wurden nicht übernommen.', '模板已复制，但有 {n} 个找不到的文件未能一并复制。'],
