  'Couleur de fond': ['Background colour', 'Color de fondo', 'Hintergrundfarbe', '背景颜色'],
  'Largeur du cadre': ['Box width', 'Ancho del marco', 'Rahmenbreite', '框宽度'],
  'Hauteur du cadre': ['Box height', 'Alto del marco', 'Rahmenhöhe', '框高度'],
  'Écoutez les voix et choisissez celle du projet : toutes les phrases seront dites par elle. Elle remplace la voix d’essai au moment où vous la validez. Elle est payée par votre compte OpenRouter s’il est branché dans les paramètres (« Services de création »), sinon par le crédit OpenRouter de Beluga Build.': ['Listen to the voices and pick the project’s one: every sentence will be spoken by it. It replaces the trial voice when you approve it. It is paid from your own OpenRouter account if it is connected in the settings (“Creative services”), otherwise from Beluga Build’s OpenRouter credit.', 'Escuche las voces y elija la del proyecto: todas las frases las dirá ella. Sustituye a la voz de prueba en el momento en que la valida. Se paga con su cuenta OpenRouter si está conectada en los ajustes («Servicios de creación»); si no, con el crédito OpenRouter de Beluga Build.', 'Hören Sie die Stimmen an und wählen Sie die des Projekts: Alle Sätze werden von ihr gesprochen. Sie ersetzt die Probestimme, sobald Sie sie bestätigen. Bezahlt wird sie über Ihr eigenes OpenRouter-Konto, wenn es in den Einstellungen verbunden ist („Kreativdienste“), sonst aus dem OpenRouter-Guthaben von Beluga Build.', '试听各个声音并选定项目的声音：所有句子都将由它朗读。确认后它会替换试听声音。如果您在设置（“创作服务”）中连接了自己的 OpenRouter 账户，费用由该账户支付，否则由 Beluga Build 的 OpenRouter 额度支付。'],
  'La voix finale est celle du projet, choisie dans « Mettre en production » : la même pour toutes les phrases.': ['The final voice is the project’s one, chosen in “Go live”: the same for every sentence.', 'La voz definitiva es la del proyecto, elegida en «Poner en producción»: la misma para todas las frases.', 'Die finale Stimme ist die des Projekts, gewählt unter „Produktiv setzen“: dieselbe für alle Sätze.', '最终声音是项目的声音，在「上线」中选择：所有句子都相同。'],
  'Autre voix ({voix})': ['Other voice ({voix})', 'Otra voz ({voix})', 'Andere Stimme ({voix})', '其他声音（{voix}）'],
