  'Le dessin pose déjà une ombre : en ajouter une la remplace.': ['The drawing already has a shadow: adding one replaces it.', 'El dibujo ya tiene una sombra: añadir una la sustituye.', 'Die Zeichnung hat bereits einen Schatten: Ein neuer ersetzt ihn.', '绘图已有阴影：添加新的会替换它。'],
  Flou: ['Blur', 'Desenfoque', 'Unschärfe', '模糊'],
  'Flou derrière': ['Background blur', 'Desenfoque de fondo', 'Hintergrundunschärfe', '背景模糊'],
  'Floute ce qu’il y a derrière la pièce (verre dépoli) : à poser sur une pièce dont le fond est transparent.': ['Blurs what is behind the piece (frosted glass): use it on a piece with a transparent fill.', 'Desenfoca lo que hay detrás de la pieza (vidrio esmerilado): úsalo en una pieza con fondo transparente.', 'Macht unscharf, was hinter dem Element liegt (Milchglas): auf einem Element mit transparentem Hintergrund verwenden.', '模糊元素后面的内容（磨砂玻璃）：用于背景透明的元素。'],
