  'Vitesse': ['Speed', 'Velocidad', 'Tempo', '速度'],
  'Changer ce texte repasse la voix « à revalider » : la nouvelle voix finale ne part que par votre clic sur « Valider la voix ».': ['Changing this text sets the voice back to “to revalidate”: the new final voice is only made when you click “Validate the voice”.', 'Cambiar este texto vuelve a poner la voz «por revalidar»: la nueva voz final solo se crea con tu clic en «Validar la voz».', 'Wenn Sie diesen Text ändern, wird die Stimme wieder „neu zu bestätigen“: Die neue finale Stimme entsteht erst durch Ihren Klick auf „Stimme bestätigen“.', '修改此文本会使语音变为“待重新确认”：新的最终语音只有在你点击“确认语音”后才会生成。'],
  'Départ dans le son': ['Start in the sound', 'Inicio en el sonido', 'Start im Ton', '声音中的起点'],
