  'Consigne de {auteur}': ['Prompt by {auteur}', 'Consigna de {auteur}', 'Vorgabe von {auteur}', '提示词作者：{auteur}'],
  'Appliquer': ['Apply', 'Aplicar', 'Anwenden', '应用'],
  'Des directions de mise en scène éprouvées. « Appliquer » écrit la demande dans le champ de l’agent : vous pouvez la compléter avant de l’envoyer.': ['Proven staging directions. “Apply” writes the request in the agent’s field: you can add to it before sending.', 'Direcciones de puesta en escena probadas. «Aplicar» escribe la petición en el campo del agente: puedes completarla antes de enviarla.', 'Bewährte Inszenierungsrichtungen. „Anwenden“ schreibt die Anfrage ins Feld des Agenten: Sie können sie vor dem Senden ergänzen.', '经过验证的演绎方向。“应用”会把请求写入智能体的输入框：发送前你可以补充。'],
  'Rechercher une création…': ['Search a creation…', 'Buscar una creación…', 'Kreation suchen…', '搜索作品……'],
  'Aucune création ne correspond à cette recherche.': ['No creation matches this search.', 'Ninguna creación coincide con esta búsqueda.', 'Keine Kreation passt zu dieser Suche.', '没有与此搜索匹配的作品。'],
  'Tous': ['All', 'Todos', 'Alle', '全部'],
  'Chercher un style (néon, typographie, 3D…)': ['Search a style (neon, typography, 3D…)', 'Buscar un estilo (neón, tipografía, 3D…)', 'Stil suchen (Neon, Typografie, 3D…)', '搜索风格（霓虹、字体、3D…）'],
