  'Les styles viennent des sources de la bibliothèque : chaque vidéo et chaque consigne restent à leur auteur.': ['Styles come from the library’s sources: every video and prompt belongs to its author.', 'Los estilos vienen de las fuentes de la biblioteca: cada vídeo y cada consigna pertenecen a su autor.', 'Die Stile stammen aus den Quellen der Bibliothek: Jedes Video und jede Vorgabe gehört seinem Urheber.', '风格来自资料库的来源：每段视频和每条提示词均归其作者所有。'],
