  'Voir l’analyse': ['See the analysis', 'Ver el análisis', 'Analyse ansehen', '查看分析'],
  'Ajoutez l’adresse d’un site d’exemples de vidéos animées : un agent l’analyse, puis vous validez avant que ses styles soient récupérés. Chaque source validée est contrôlée chaque nuit, et ses nouveautés arrivent avec la marque « Nouveau ».': ['Add the address of a site with animated video examples: an agent analyses it, then you approve before its styles are fetched. Every approved source is checked each night, and its new items arrive marked “New”.', 'Añada la dirección de un sitio con ejemplos de vídeos animados: un agente lo analiza y usted valida antes de que se recuperen sus estilos. Cada fuente validada se revisa cada noche, y sus novedades llegan con la marca «Nuevo».', 'Fügen Sie die Adresse einer Website mit Beispielen animierter Videos hinzu: Ein Agent analysiert sie, dann geben Sie frei, bevor ihre Stile abgerufen werden. Jede freigegebene Quelle wird jede Nacht geprüft, und ihre Neuheiten erscheinen mit der Markierung „Neu“.', '添加一个动画视频示例网站的地址：智能体先分析，您确认后才会获取其风格。每个已确认的来源每晚检查一次，新内容会带“新”标记。'],
  'Adresse d’un site (https://…)': ['Site address (https://…)', 'Dirección de un sitio (https://…)', 'Adresse einer Website (https://…)', '网站地址（https://…）'],
