  'Le temps de travail des agents, jour par jour et projet par projet.': ['Agent working time, day by day and project by project.', 'El tiempo de trabajo de los agentes, día a día y proyecto a proyecto.', 'Die Arbeitszeit der Agenten, Tag für Tag und Projekt für Projekt.', '智能体的工作时间，按天、按项目统计。'],
