  'Chaque tâche exécutée : ses tours, sa durée, ses jetons et sa note.': ['Every task run: its turns, duration, tokens and score.', 'Cada tarea ejecutada: sus turnos, su duración, sus tokens y su nota.', 'Jede ausgeführte Aufgabe: Durchläufe, Dauer, Token und Bewertung.', '每个已执行的任务：轮次、时长、令牌和评分。'],
  'Mémoire et compétences': ['Memory and skills', 'Memoria y competencias', 'Gedächtnis und Kompetenzen', '记忆与技能'],
  'Ce que la mémoire a appris, combien de fois elle a été consultée, et ce qui a vraiment servi.': ['What the memory learned, how often it was consulted, and what was really useful.', 'Lo que la memoria ha aprendido, cuántas veces se ha consultado y lo que realmente ha servido.', 'Was das Gedächtnis gelernt hat, wie oft es abgefragt wurde und was wirklich genützt hat.', '记忆学到了什么、被查询了多少次，以及哪些内容真正派上了用场。'],
  'Services': ['Services', 'Servicios', 'Dienste', '服务'],
  'Les contrôles des sites surveillés, leurs pannes et leur temps de réponse.': ['Checks of monitored sites, their outages and response time.', 'Los controles de los sitios vigilados, sus caídas y su tiempo de respuesta.', 'Die Prüfungen der überwachten Websites, ihre Ausfälle und Antwortzeiten.', '受监控网站的检查、故障和响应时间。'],
  "Les visuels et vidéos créés, leurs exports et ce qu'ils ont coûté.": ['Visuals and videos created, their exports and what they cost.', 'Los visuales y vídeos creados, sus exportaciones y lo que han costado.', 'Erstellte Visuals und Videos, ihre Exporte und ihre Kosten.', '已创建的视觉和视频、其导出以及花费。'],
  "Le nombre d'accès rangés, par projet et par type. Aucun secret n'est affiché ici.": ['The number of stored credentials, by project and by type. No secret is shown here.', 'El número de accesos guardados, por proyecto y por tipo. Aquí no se muestra ningún secreto.', 'Die Anzahl gespeicherter Zugänge, nach Projekt und Typ. Hier wird kein Geheimnis angezeigt.', '已保存访问凭据的数量，按项目和类型统计。此处不显示任何机密。'],
  'Les sauvegardes prises, leur volume et leurs échecs.': ['Backups taken, their size and their failures.', 'Las copias de seguridad realizadas, su volumen y sus fallos.', 'Erstellte Sicherungen, ihr Umfang und ihre Fehlschläge.', '已完成的备份、容量及失败情况。'],
  'Les visites des sites suivis, leurs visiteurs et les objectifs atteints.': ['Visits to tracked sites, their visitors and goals reached.', 'Las visitas de los sitios seguidos, sus visitantes y los objetivos alcanzados.', 'Besuche der erfassten Websites, ihre Besucher und erreichte Ziele.', '受跟踪网站的访问、访客和已达成的目标。'],
  'Les demandes des clients et les messages échangés.': ['Client requests and the messages exchanged.', 'Las solicitudes de los clientes y los mensajes intercambiados.', 'Kundenanfragen und ausgetauschte Nachrichten.', '客户请求和往来消息。'],
  'Les contenus préparés, les actions menées et les ventes relevées.': ['Content prepared, actions carried out and sales recorded.', 'Los contenidos preparados, las acciones realizadas y las ventas registradas.', 'Vorbereitete Inhalte, durchgeführte Aktionen und erfasste Verkäufe.', '已准备的内容、已执行的行动和已记录的销售。'],
  'Les notes créées et modifiées.': ['Notes created and edited.', 'Las notas creadas y modificadas.', 'Erstellte und geänderte Notizen.', '已创建和修改的笔记。'],
