  "Tours d'agent": ['Agent turns', 'Turnos de agente', 'Agenten-Durchläufe', '智能体轮次'],
  'Le temps de travail des agents chaque jour (les barres) et le nombre de tâches (la ligne), tous moteurs confondus.': ['Agent working time each day (bars) and number of tasks (line), all engines combined.', 'El tiempo de trabajo de los agentes cada día (barras) y el número de tareas (línea), todos los motores juntos.', 'Die tägliche Arbeitszeit der Agenten (Balken) und die Zahl der Aufgaben (Linie), alle Engines zusammen.', '智能体每天的工作时间（柱）和任务数（线），所有引擎合计。'],
  'Tâches': ['Tasks', 'Tareas', 'Aufgaben', '任务'],
  'Aucune consommation relevée sur la période.': ['No usage recorded over the period.', 'Ningún consumo registrado en el periodo.', 'Kein Verbrauch im Zeitraum erfasst.', '该期间内无用量记录。'],
