  'Part du temps': ['Share of time', 'Parte del tiempo', 'Zeitanteil', '时间占比'],
  "Chaque tâche exécutée sur la période, avec ses jetons d'entrée et de sortie réels, la plus récente en tête.": ['Every task run over the period, with its real input and output tokens, most recent first.', 'Cada tarea ejecutada en el periodo, con sus tokens reales de entrada y salida, la más reciente primero.', 'Jede im Zeitraum ausgeführte Aufgabe mit ihren tatsächlichen Eingabe- und Ausgabe-Token, die neueste zuerst.', '该期间内执行的每个任务及其真实的输入和输出令牌，最新的排在最前。'],
  'Aucune tâche exécutée sur la période.': ['No task run over the period.', 'Ninguna tarea ejecutada en el periodo.', 'Keine Aufgabe im Zeitraum ausgeführt.', '该期间内没有执行任何任务。'],
  'Tâche': ['Task', 'Tarea', 'Aufgabe', '任务'],
  'Dernier tour': ['Last turn', 'Último turno', 'Letzter Durchlauf', '最后一轮'],
  "Pour chaque tâche terminée : les jetons réellement consommés par le moteur, les sujets de mémoire ouverts et le temps qu'ils ont pris, et une estimation de qualité.": ['For each finished task: the tokens really used by the engine, the memory topics opened and the time they took, and a quality estimate.', 'Para cada tarea terminada: los tokens realmente consumidos por el motor, los temas de memoria abiertos y el tiempo que tomaron, y una estimación de calidad.', 'Für jede abgeschlossene Aufgabe: die tatsächlich verbrauchten Token, die geöffneten Gedächtnisthemen und ihre Dauer sowie eine Qualitätsschätzung.', '每个已完成任务：引擎实际消耗的令牌、打开的记忆主题及其耗时，以及质量估计。'],
  'sur la période': ['over the period', 'en el periodo', 'im Zeitraum', '该期间内'],
