  'Consultations': ['Lookups', 'Consultas', 'Abfragen', '查询'],
  '{v0} en moyenne': ['{v0} on average', '{v0} de media', 'im Schnitt {v0}', '平均 {v0}'],
  'Pertinence': ['Relevance', 'Pertinencia', 'Relevanz', '相关度'],
  'des blocs trouvés ont été servis': ['of blocks found were served', 'de los bloques encontrados se sirvieron', 'der gefundenen Blöcke wurden geliefert', '找到的块已被提供'],
  'Ce que la mémoire a appris, jour par jour': ['What the memory learned, day by day', 'Lo que la memoria ha aprendido, día a día', 'Was das Gedächtnis gelernt hat, Tag für Tag', '记忆每天学到的内容'],
  'Les barres : les connaissances enregistrées chaque jour. La ligne : les consultations de la mémoire par les agents.': ['Bars: knowledge recorded each day. Line: memory lookups by agents.', 'Barras: los conocimientos registrados cada día. Línea: las consultas de la memoria por los agentes.', 'Balken: täglich gespeichertes Wissen. Linie: Gedächtnisabfragen der Agenten.', '柱：每天记录的知识。线：智能体对记忆的查询。'],
  "Rien d'enregistré ni de consulté sur la période.": ['Nothing recorded or looked up over the period.', 'Nada registrado ni consultado en el periodo.', 'Im Zeitraum nichts gespeichert oder abgefragt.', '该期间内没有记录或查询。'],
  '{v0} modifications': ['{v0} edits', '{v0} modificaciones', '{v0} Änderungen', '{v0} 次修改'],
  "{v0} refus de la porte d'écriture": ['{v0} rejected by the write gate', '{v0} rechazos de la puerta de escritura', '{v0} Ablehnungen durch die Schreibschranke', '写入关口拒绝 {v0} 次'],
  '{v0} compétences créées': ['{v0} skills created', '{v0} competencias creadas', '{v0} Kompetenzen erstellt', '创建了 {v0} 项技能'],
  'Pertinence des consultations, par sujet': ['Lookup relevance, by topic', 'Pertinencia de las consultas, por tema', 'Relevanz der Abfragen, nach Thema', '按主题统计的查询相关度'],
  "Pour chaque sujet consulté : le nombre d'appels, leur durée moyenne, et la part des blocs trouvés qui ont réellement été servis à l'agent.": ['For each topic looked up: the number of calls, their average duration, and the share of blocks found that were really served to the agent.', 'Para cada tema consultado: el número de llamadas, su duración media y la parte de los bloques encontrados que realmente se sirvieron al agente.', 'Für jedes abgefragte Thema: die Zahl der Aufrufe, ihre durchschnittliche Dauer und der Anteil der gefundenen Blöcke, die dem Agenten wirklich geliefert wurden.', '每个被查询的主题：调用次数、平均耗时，以及找到的块中真正提供给智能体的比例。'],
  'Aucune consultation sur la période.': ['No lookup over the period.', 'Ninguna consulta en el periodo.', 'Keine Abfrage im Zeitraum.', '该期间内没有查询。'],
  'Appels': ['Calls', 'Llamadas', 'Aufrufe', '调用'],
  'Blocs demandés': ['Blocks requested', 'Bloques pedidos', 'Angefragte Blöcke', '请求的块'],
  'Blocs servis': ['Blocks served', 'Bloques servidos', 'Gelieferte Blöcke', '提供的块'],
  'Chaque compétence du pool : quand elle est née, combien de fois elle a été servie, et ce que les agents en ont dit. Ces compteurs courent depuis sa création, pas seulement sur la période.': ['Every skill in the pool: when it was created, how often it was served, and what agents said about it. These counters run since its creation, not just over the period.', 'Cada competencia del pool: cuándo nació, cuántas veces se sirvió y lo que dijeron de ella los agentes. Estos contadores corren desde su creación, no solo en el periodo.', 'Jede Kompetenz im Pool: wann sie entstand, wie oft sie geliefert wurde und was die Agenten dazu sagten. Diese Zähler laufen seit ihrer Erstellung, nicht nur im Zeitraum.', '技能池中的每项技能：何时创建、被提供了多少次，以及智能体的评价。这些计数自技能创建起累计，而不仅限于该期间。'],
