  'Copier le nom': ['Copy the name', 'Copiar el nombre', 'Namen kopieren', '复制名称'],
  'Ouvrir sur GitHub': ['Open on GitHub', 'Abrir en GitHub', 'Auf GitHub öffnen', '在 GitHub 上打开'],
  'Nouvelle branche…': ['New branch…', 'Nueva rama…', 'Neuer Branch…', '新分支…'],
  'Reprendre une branche': ['Take over a branch', 'Retomar una rama', 'Einen Branch übernehmen', '接手一个分支'],
  'Rechercher une branche': ['Search for a branch', 'Buscar una rama', 'Branch suchen', '搜索分支'],
  'Aucune branche ne correspond.': ['No branch matches.', 'Ninguna rama coincide.', 'Kein Branch passt.', '没有匹配的分支。'],
  'Aucune autre branche de travail dans le dépôt.': ['No other working branch in the repository.', 'No hay otra rama de trabajo en el repositorio.', 'Kein anderer Arbeits-Branch im Repository.', '仓库中没有其他工作分支。'],
  'Rechercher un modèle': ['Search for a model', 'Buscar un modelo', 'Modell suchen', '搜索模型'],
  'Aucun modèle ne correspond.': ['No model matches.', 'Ningún modelo coincide.', 'Kein Modell passt.', '没有匹配的模型。'],
  'Afficher plus': ['Show more', 'Mostrar más', 'Mehr anzeigen', '显示更多'],
  "Cette carte n'a modifié aucun fichier.": ["This card did not change any file.", "Esta tarjeta no modificó ningún archivo.", "Diese Karte hat keine Datei geändert.", "此卡片未修改任何文件。"],
  "Cette carte a travaillé, mais sa branche n'est plus retrouvée dans le dépôt.": ["This card did work, but its branch can no longer be found in the repository.", "Esta tarjeta trabajó, pero su rama ya no se encuentra en el repositorio.", "Diese Karte hat gearbeitet, aber ihr Branch ist im Repository nicht mehr auffindbar.", "此卡片已执行过工作，但其分支在仓库中已找不到。"],
  "Aucun fichier touché par cette branche.": ["No file touched by this branch.", "Ningún archivo tocado por esta rama.", "Keine Datei von diesem Branch berührt.", "该分支未改动任何文件。"],
  '{n} aides au travail': ['{n} helpers at work', '{n} ayudantes trabajando', '{n} Helfer bei der Arbeit', '{n} 个助手在工作'],
  'Allumé tout seul : la demande est complexe. Le cadrage pose plus de questions puis rend un plan à sa taille.': ['Turned on automatically: the request is complex. Scoping asks more questions, then returns a plan sized to it.', 'Activado automáticamente: la solicitud es compleja. El encuadre hace más preguntas y luego entrega un plan a su medida.', 'Automatisch eingeschaltet: Die Anfrage ist komplex. Die Klärung stellt mehr Fragen und liefert dann einen passenden Plan.', '已自动开启：请求较复杂。梳理阶段会多问几个问题，再给出与之匹配的计划。'],
  'Le mode Création': ['Creation mode', 'El modo Creación', 'Der Kreativmodus', '创作模式'],
  'L’agent de la carte devient chef d’orchestre : au lieu de tout faire seul, il fait travailler plusieurs modèles ensemble.': ['The card’s agent becomes a conductor: instead of doing everything alone, it gets several models working together.', 'El agente de la tarjeta se convierte en director de orquesta: en lugar de hacerlo todo solo, hace trabajar a varios modelos juntos.', 'Der Agent der Karte wird zum Dirigenten: Statt alles allein zu machen, lässt er mehrere Modelle zusammenarbeiten.', '卡片的智能体变成指挥：不再独自完成一切，而是让多个模型协同工作。'],
  'Il confie le texte, le code et les avis à d’autres moteurs du serveur.': ['It hands text, code and reviews to other engines on the server.', 'Confía el texto, el código y las opiniones a otros motores del servidor.', 'Er übergibt Text, Code und Gutachten an andere Engines des Servers.', '它把文本、代码和评审交给服务器上的其他引擎。'],
  'Leurs propositions sont départagées par un juge, puis il assemble le meilleur rendu.': ['A judge picks between their proposals, then it assembles the best result.', 'Un juez desempata sus propuestas y luego ensambla el mejor resultado.', 'Ein Richter entscheidet zwischen ihren Vorschlägen, dann setzt er das beste Ergebnis zusammen.', '由评审在它们的方案中择优，再组装出最佳结果。'],
  'Utile pour un travail créatif ou délicat ; plus lent et plus coûteux qu’un agent seul.': ['Useful for creative or delicate work; slower and more costly than a single agent.', 'Útil para un trabajo creativo o delicado; más lento y más costoso que un solo agente.', 'Nützlich für kreative oder heikle Arbeit; langsamer und teurer als ein einzelner Agent.', '适合创意或精细的工作；比单个智能体更慢、更贵。'],
  'Le choix vaut pour cette carte seulement, et un nouveau clic l’éteint.': ['The choice applies to this card only, and another click turns it off.', 'La elección vale solo para esta tarjeta, y otro clic la desactiva.', 'Die Wahl gilt nur für diese Karte, ein weiterer Klick schaltet sie aus.', '此选择仅对本卡片有效，再点一次即可关闭。'],
  'Activer le mode Création': ['Turn on Creation mode', 'Activar el modo Creación', 'Kreativmodus einschalten', '开启创作模式'],
