  "Le site tarde à s’afficher ? Il refuse peut-être d’être affiché ici :": ["Site slow to show? It may refuse to be displayed here:", "¿El sitio tarda en mostrarse? Quizá se niega a mostrarse aquí:", "Die Seite erscheint nicht? Vielleicht verweigert sie die Anzeige hier:", "站点迟迟不显示？它可能拒绝在此处显示："],
  "ouvrez-le dans un onglet": ["open it in a tab", "ábralo en una pestaña", "in einem Tab öffnen", "在标签页中打开它"],
  "Lancement automatique allumé : la tâche partira seule dès la compréhension prête.": ["Auto-start on: the task will start by itself as soon as the understanding is ready.", "Inicio automático activado: la tarea se iniciará sola en cuanto la comprensión esté lista.", "Autostart an: Die Aufgabe startet von selbst, sobald das Verständnis bereit ist.", "自动启动已开启：理解一就绪，任务将自行启动。"],
  "Lancement automatique : lancer la tâche seule dès que la compréhension est prête.": ["Auto-start: start the task by itself as soon as the understanding is ready.", "Inicio automático: iniciar la tarea sola en cuanto la comprensión esté lista.", "Autostart: die Aufgabe von selbst starten, sobald das Verständnis bereit ist.", "自动启动：理解一就绪便自行启动任务。"],
  "Lancement automatique": ["Auto-start", "Inicio automático", "Autostart", "自动启动"],
  "Auto": ["Auto", "Auto", "Auto", "自动"],
  "Auto et l’horloge servent tous deux à lancer la carte sans que vous soyez là.": ["Auto and the clock both start the card without you being there.", "Auto y el reloj sirven los dos para lanzar la tarjeta sin que usted esté presente.", "Auto und die Uhr starten beide die Karte, ohne dass Sie dabei sind.", "“自动”和时钟都用于在您不在场时启动卡片。"],
