  "Vidéos Kling et Hailuo, payées sur votre solde Higgsfield.": ["Kling and Hailuo videos, paid from your Higgsfield balance.", "Vídeos Kling y Hailuo, pagados con su saldo de Higgsfield.", "Kling- und Hailuo-Videos, bezahlt aus Ihrem Higgsfield-Guthaben.", "Kling 与 Hailuo 视频，从您的 Higgsfield 余额中扣费。"],
  "Les vidéos Seedance de ByteDance, avec le son.": ["ByteDance’s Seedance videos, with sound.", "Los vídeos Seedance de ByteDance, con sonido.", "Die Seedance-Videos von ByteDance, mit Ton.", "字节跳动的 Seedance 视频，带声音。"],
  "Veo, Kling et Wan, payés sur votre crédit Freepik (Magnific).": ["Veo, Kling and Wan, paid from your Freepik (Magnific) credit.", "Veo, Kling y Wan, pagados con su crédito de Freepik (Magnific).", "Veo, Kling und Wan, bezahlt aus Ihrem Freepik-Guthaben (Magnific).", "Veo、Kling 与 Wan，从您的 Freepik（Magnific）额度中扣费。"],
  "Veo, Kling et Seedance depuis votre espace Krea.": ["Veo, Kling and Seedance from your Krea workspace.", "Veo, Kling y Seedance desde su espacio de Krea.", "Veo, Kling und Seedance aus Ihrem Krea-Arbeitsbereich.", "通过您的 Krea 工作区使用 Veo、Kling 与 Seedance。"],
  "Gen-4.5 et Veo 3.1, payés en crédits Runway.": ["Gen-4.5 and Veo 3.1, paid in Runway credits.", "Gen-4.5 y Veo 3.1, pagados con créditos de Runway.", "Gen-4.5 und Veo 3.1, bezahlt mit Runway-Credits.", "Gen-4.5 与 Veo 3.1，以 Runway 点数支付。"],
  "Veo, Kling et Seedance au prix publié par fal.ai.": ["Veo, Kling and Seedance at the price published by fal.ai.", "Veo, Kling y Seedance al precio publicado por fal.ai.", "Veo, Kling und Seedance zum von fal.ai veröffentlichten Preis.", "Veo、Kling 与 Seedance，按 fal.ai 公布的价格计费。"],
  "Veo, Kling et Seedance hébergés par Replicate.": ["Veo, Kling and Seedance hosted by Replicate.", "Veo, Kling y Seedance alojados por Replicate.", "Veo, Kling und Seedance, gehostet von Replicate.", "由 Replicate 托管的 Veo、Kling 与 Seedance。"],
  "Votre propre compte pour la voix finale et la musique, à la place de celui de Beluga Build.": ["Your own account for the final voice and the music, instead of Beluga Build’s.", "Su propia cuenta para la voz definitiva y la música, en lugar de la de Beluga Build.", "Ihr eigenes Konto für die finale Stimme und die Musik, anstelle des Kontos von Beluga Build.", "用您自己的账户制作最终配音和音乐，取代 Beluga Build 的账户。"],
