  "Brancher": ["Connect", "Conectar", "Verbinden", "连接"],
  "Changer la clé": ["Change the key", "Cambiar la clave", "Schlüssel ändern", "更换密钥"],
  "Tester": ["Test", "Probar", "Testen", "测试"],
  "Retirer {service} ?": ["Remove {service}?", "¿Retirar {service}?", "{service} entfernen?", "移除 {service}？"],
  "Branchez vos propres comptes : l’agent du Studio s’en sert pour fabriquer les extraits d’une vidéo, et votre compte OpenRouter remplace celui de Beluga Build pour la voix et la musique. Chaque extrait passe d’abord par un devis que vous validez d’un clic.": ["Connect your own accounts: the Studio agent uses them to make the clips of a video, and your OpenRouter account replaces Beluga Build’s for the voice and the music. Every clip first goes through a quote you approve with one click.", "Conecte sus propias cuentas: el agente del Studio las usa para fabricar los fragmentos de un vídeo, y su cuenta OpenRouter sustituye a la de Beluga Build para la voz y la música. Cada fragmento pasa antes por un presupuesto que usted valida con un clic.", "Verbinden Sie Ihre eigenen Konten: Der Studio-Agent nutzt sie, um die Clips eines Videos zu erstellen, und Ihr OpenRouter-Konto ersetzt das von Beluga Build für Stimme und Musik. Jeder Clip geht zuerst durch einen Kostenvoranschlag, den Sie mit einem Klick bestätigen.", "连接您自己的账户：Studio 智能体用它们制作视频片段，您的 OpenRouter 账户将取代 Beluga Build 的账户来制作配音和音乐。每个片段都会先生成报价，由您一键确认。"],
  "Chargement…": ["Loading…", "Cargando…", "Wird geladen…", "加载中…"],
  "choix non retenu": ["choice not saved", "elección no guardada", "Auswahl nicht gespeichert", "选择未保存"],
  "Vos services de création": ["Your creative services", "Sus servicios de creación", "Ihre Kreativdienste", "您的创作服务"],
  "Modèle retenu pour cette vidéo : {modele}.": ["Model chosen for this video: {modele}.", "Modelo elegido para este vídeo: {modele}.", "Für dieses Video gewähltes Modell: {modele}.", "此视频选用的模型：{modele}。"],
  "Pour fabriquer des extraits vidéo, branchez un de vos comptes (Runway, Krea, fal.ai, Replicate, Freepik, BytePlus ou Higgsfield) : collez sa clé dans les paramètres. Dès qu’un service est branché, ses modèles apparaissent ici.": ["To make video clips, connect one of your accounts (Runway, Krea, fal.ai, Replicate, Freepik, BytePlus or Higgsfield): paste its key in the settings. As soon as a service is connected, its models appear here.", "Para fabricar fragmentos de vídeo, conecte una de sus cuentas (Runway, Krea, fal.ai, Replicate, Freepik, BytePlus o Higgsfield): pegue su clave en los ajustes. En cuanto un servicio esté conectado, sus modelos aparecerán aquí.", "Um Videoclips zu erstellen, verbinden Sie eines Ihrer Konten (Runway, Krea, fal.ai, Replicate, Freepik, BytePlus oder Higgsfield): Fügen Sie seinen Schlüssel in den Einstellungen ein. Sobald ein Dienst verbunden ist, erscheinen hier seine Modelle.", "要制作视频片段，请连接您的一个账户（Runway、Krea、fal.ai、Replicate、Freepik、BytePlus 或 Higgsfield）：在设置中粘贴其密钥。服务一旦连接，其模型就会显示在这里。"],
  "Ouvrir les paramètres": ["Open settings", "Abrir los ajustes", "Einstellungen öffnen", "打开设置"],
  "Choisissez le modèle qui fabriquera les extraits de cette vidéo.": ["Choose the model that will make the clips of this video.", "Elija el modelo que fabricará los fragmentos de este vídeo.", "Wählen Sie das Modell, das die Clips dieses Videos erstellt.", "选择用于制作此视频片段的模型。"],
